from collections import deque
from typing import List

def process_input_list(n: int, input_list: List[int]) -> int:
    tfe = deque()

    for x in input_list:
        temp = x
        while tfe and tfe[-1] == temp:
            temp += 1
            tfe.pop()
        tfe.append(temp)

    return len(tfe)
